def make_a_pile(n):
    pile = [n]
    current_number = n
    while len(pile) < n:
        if len(pile) % 2 == 0:  # Even index in pile means this is an odd level (1st, 3rd, etc.)
            current_number += 2 if current_number % 2 == 0 else 1  # Next odd number
        else:  # Odd index in pile means this is an even level (2nd, 4th, etc.)
            current_number += 1 if current_number % 2 == 0 else 2  # Next even number
        pile.append(current_number)
    return pile
